// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {SimpleWallet} from "../src/SimpleWallet.sol";

contract InvMutTest is Test {
    SimpleWallet c;
    function setUp() public { c = new SimpleWallet(); }

    function testFuzz_property(uint256 amount) public {
        amount = bound(amount, 0, 1 ether);

        Reverter rev = new Reverter();

        vm.deal(address(c), amount);

        GasEater eater = new GasEater();

        vm.deal(address(c), amount);

        uint256 before = address(c).balance;

        bool ok;
        try c.sendMoney(address(eater), amount) {
            ok = true;
        } catch {
            ok = false;
        }

        if (amount > 0) {
            assertTrue(ok && address(c).balance == before - amount);
        } else {
            assertTrue(ok && address(c).balance == before);
        }
    }
}

contract GasEater {
    fallback() external payable {
        for (uint256 i = 0; i < 50; i++) {
            assembly { sstore(i, i) }
        }
    }
}

contract Reverter { fallback() external payable { revert(); } }
